CREATE TYPE change_order_status AS ENUM ('DRAFT','SUBMITTED','ACCEPTED','DECLINED','EXPIRED','SUPERSEDED');
CREATE TYPE support_status AS ENUM ('OPEN','INVESTIGATING','WAITING_CUSTOMER','WAITING_CONTRACTOR','RESOLVED','CLOSED');
CREATE TYPE notification_channel AS ENUM ('IN_APP','EMAIL','SMS','PUSH','PHONE');
CREATE TABLE property_systems (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), vertical_id uuid NOT NULL REFERENCES verticals(id), name text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', installed_on date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE warranties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_system_id uuid REFERENCES property_systems(id), service_record_id uuid REFERENCES service_records(id), provider_name text NOT NULL, warranty_type text NOT NULL, starts_on date, expires_on date, terms_url text, status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), CHECK(property_system_id IS NOT NULL OR service_record_id IS NOT NULL));
CREATE TABLE change_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), version integer NOT NULL, status change_order_status NOT NULL DEFAULT 'DRAFT', reason text NOT NULL, explanation text NOT NULL, attachment_keys jsonb NOT NULL DEFAULT '[]', contractor_subtotal_cents bigint NOT NULL DEFAULT 0, platform_fee_cents bigint NOT NULL DEFAULT 0, tax_cents bigint NOT NULL DEFAULT 0, customer_total_cents bigint NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'CAD', expires_at timestamptz NOT NULL, accepted_at timestamptz, accepted_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id, version));
CREATE UNIQUE INDEX change_orders_one_submitted ON change_orders(job_id) WHERE status = 'SUBMITTED';
CREATE TABLE change_order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), change_order_id uuid NOT NULL REFERENCES change_orders(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, description text, quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents >= 0), subtotal_cents bigint NOT NULL CHECK(subtotal_cents >= 0), material_metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), invoice_number text NOT NULL UNIQUE, subtotal_cents bigint NOT NULL, platform_fee_cents bigint NOT NULL, tax_cents bigint NOT NULL, total_cents bigint NOT NULL, currency char(3) NOT NULL, issued_at timestamptz NOT NULL DEFAULT now(), pdf_key text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES users(id), contractor_id uuid REFERENCES contractors(id), job_id uuid REFERENCES jobs(id), subject text NOT NULL, description text NOT NULL, status support_status NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), support_ticket_id uuid NOT NULL UNIQUE REFERENCES support_tickets(id), job_id uuid NOT NULL REFERENCES jobs(id), customer_id uuid NOT NULL REFERENCES users(id), contractor_id uuid NOT NULL REFERENCES contractors(id), status support_status NOT NULL DEFAULT 'OPEN', resolution text, refund_decision_cents bigint, resolved_by uuid REFERENCES users(id), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dispute_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid NOT NULL REFERENCES disputes(id), submitted_by uuid NOT NULL REFERENCES users(id), attachment_key text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_user_id uuid NOT NULL REFERENCES users(id), channel notification_channel NOT NULL DEFAULT 'IN_APP', event_type text NOT NULL, title text NOT NULL, body text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_recipient_idx ON notifications(recipient_user_id, read_at, created_at DESC);
CREATE TABLE domain_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE INDEX domain_events_unpublished_idx ON domain_events(published_at, occurred_at) WHERE published_at IS NULL;
CREATE TABLE customer_contractor_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), contractor_id uuid NOT NULL REFERENCES contractors(id), acquisition_source text NOT NULL, first_platform_job_id uuid NOT NULL REFERENCES jobs(id), last_platform_job_id uuid NOT NULL REFERENCES jobs(id), repeat_job_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id, contractor_id));
CREATE TABLE fee_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vertical_id uuid REFERENCES verticals(id), contractor_id uuid REFERENCES contractors(id), relationship_stage text NOT NULL, take_rate_bps integer NOT NULL CHECK(take_rate_bps BETWEEN 0 AND 10000), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(vertical_id IS NOT NULL OR contractor_id IS NOT NULL));
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES payment_transactions(id), amount_cents bigint NOT NULL CHECK(amount_cents > 0), reason text NOT NULL, status payment_status NOT NULL DEFAULT 'PENDING', idempotency_key text NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contractor_id uuid NOT NULL REFERENCES contractors(id), job_id uuid NOT NULL REFERENCES jobs(id), amount_cents bigint NOT NULL CHECK(amount_cents >= 0), currency char(3) NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','HELD','ELIGIBLE','RELEASED','REVERSED')), eligible_at timestamptz, released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contractor_id,job_id));
